"""TP-D TOPIK II 듣기: second batch (v1.19, RYU 2026-11-25: about 30 questions per lesson page, 5 shown at a time).
Right answer written first; tools/topik_bank.py shuffles the choices (picture questions are shuffled here)."""
import random
from common import au, Q, S, pics, O4

def L(s, o, x):                      # single question, right answer first
    return Q(o, 0, x, au(s))

def P(script, rows, x):              # picture question: rows[0] is right; order mixed with a fixed seed
    r = random.Random(script); idx = list(range(4)); r.shuffle(idx)
    return Q(O4, idx.index(0), x, au(script), p=pics([rows[i] for i in idx]))

def T(script, qs):                   # set: qs = [(question, [right, ...], x)]
    return S([(q, o, 0, x) for q, o, x in qs], au=au(script))

